#!/usr/bin/env node
/**
 * Golden-pin gate: the v2 byte pins may only move inside a declared rebuild
 * window, and the declaration is a `Rebuild-Window: R1` commit trailer.
 *
 * The pins are the two committed golden fixture trees — manifests,
 * content-addressed packs, directory pages, and `expected-hashes.json`:
 *
 *   - `crates/stt-core/tests/fixtures/v2-golden/**` — the WRITER's oracle,
 *     checked by `crates/stt-core/tests/v2_golden.rs`, regenerated by
 *     `crates/stt-core/examples/make-golden-fixture.rs`.
 *   - `packages/core/test/fixtures/**` — the READER's oracle (six datasets:
 *     `legacy-shape`, `packed-golden`, `paged-golden`, `paged-golden-single`,
 *     `v2-golden`, `v2-golden-tracks`), checked by `packed-v2-golden.test.ts`,
 *     `packed-golden.test.ts`, `paged-directory.test.ts` and
 *     `legacy-shape-backcompat.test.ts`, regenerated by
 *     `packages/core/scripts/make-v2-golden.sh`.
 *
 * The second tree was added on 2026-08-10, after the Phase 0 audit found ~110
 * churning golden objects sitting entirely outside this gate while carrying
 * exactly the same regression-oracle role. Watching only the writer side was
 * the more dangerous half to leave open: a reader fixture re-blessed on its own
 * hides an encoder change behind a reader that was taught to accept it.
 *
 * They are the format's regression oracles, and the rule governing them
 * existed only as prose:
 * "Golden byte pins may change only with intentional, reviewed encoder
 * changes" (optimization-problems-2026-08.md §13.1) and "Golden byte pins
 * change once, intentionally, reviewed" (optimization-informed-design-2026-08.md
 * §6, Phase 4). This file makes it mechanical.
 *
 * Why a gate and not a convention: a red golden test has exactly two causes,
 * and they want opposite responses. Either the encoder drifted — in which case
 * re-blessing the fixture destroys the only evidence — or bytes moved on
 * purpose, which is a fleet-wide event. The two historical pin movements (the
 * FNV-1a id migration, the Arrow-54 metadata-order gap) each forced a full
 * re-upload; the 2026-07-26 break cost 29.3 GiB across 1,324 objects, 100%
 * re-uploaded. Re-blessing is the cheap-looking move and the expensive one.
 *
 * Enforcement is per COMMIT, not per aggregate diff. A branch that moves a pin
 * and then reverts it still had an unreviewed pin movement in its history, and
 * per-commit granularity is also what makes the flag cheap: the trailer goes on
 * the one commit that does the rebuild, not on the whole branch.
 *
 * Trailer, not grep. `Rebuild-Window: R1` must sit in the message's trailer
 * block (the last paragraph), so quoting the phrase in prose — including in a
 * commit that explains this gate — does not flag anything.
 *
 * No GitHub PR metadata is used: base resolution falls back to a merge-base
 * with `origin/main`, because per backlog T2 GitHub Actions has never actually
 * executed in this repo and every gate here is enforced by local discipline.
 *
 * Usage:
 *   node .github/scripts/check-golden-pins.mjs               # exit 1 on drift
 *   node .github/scripts/check-golden-pins.mjs --base <ref>
 *   node .github/scripts/check-golden-pins.mjs --working-tree
 *   node --test .github/scripts/check-golden-pins.test.mjs   # this gate's tests
 */
import { execFileSync } from 'node:child_process';
import { existsSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const REPO_ROOT = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '../..',
);

/**
 * The watched set. Two rules, deliberately overlapping:
 *
 * - `dir` — everything under a golden fixture tree (manifests, packs,
 *   directory pages, and the hash pin itself). Both the writer-side and the
 *   reader-side trees qualify: they answer the same question, "did the bytes
 *   move?", and re-blessing either one destroys the same evidence.
 * - `basename` — any file called `expected-hashes.json` ANYWHERE. The hash pin
 *   is the one file whose whole purpose is to be compared byte-for-byte, so it
 *   stays watched even if someone relocates it out of the fixture tree.
 *
 * `guard` names what must exist in the working tree for the rule to mean
 * anything (see `missingPinnedRoots`). `oracle` and `regen` are per-root
 * because the two trees have different ones, and a failure message that names
 * the wrong regenerator sends the reader to re-bless the wrong tree.
 */
export const PINNED_ROOTS = [
  {
    kind: 'dir',
    path: 'crates/stt-core/tests/fixtures/v2-golden',
    guard: 'crates/stt-core/tests/fixtures/v2-golden',
    what: 'the writer-side golden fixture tree (manifests, packs, directory pages)',
    oracle: 'crates/stt-core/tests/v2_golden.rs',
    regen: 'cargo run -p stt-core --example make-golden-fixture',
  },
  {
    kind: 'dir',
    path: 'packages/core/test/fixtures',
    guard: 'packages/core/test/fixtures',
    what: 'the reader-side golden fixture trees (legacy-shape, packed-golden, paged-golden, paged-golden-single, v2-golden, v2-golden-tracks)',
    oracle: 'packages/core/test/packed-v2-golden.test.ts',
    regen: 'packages/core/scripts/make-v2-golden.sh',
  },
  {
    kind: 'basename',
    path: 'expected-hashes.json',
    guard: 'crates/stt-core/tests/fixtures/v2-golden/expected-hashes.json',
    what: 'the golden hash pin',
    oracle: 'crates/stt-core/tests/v2_golden.rs',
    regen: 'cargo run -p stt-core --example make-golden-fixture',
  },
];

/** The writer-side oracle; kept as a named constant because it is the one the
 * §13.1 rationale is written about. Per-root values live on `PINNED_ROOTS`. */
export const ORACLE_TEST = 'crates/stt-core/tests/v2_golden.rs';
/** The writer-side regenerator, named so the teaching message is actionable. */
export const REGEN_CMD = 'cargo run -p stt-core --example make-golden-fixture';

export const TRAILER_KEY = 'Rebuild-Window';
export const TRAILER_VALUE = 'R1';

/** True when a repo-relative path is one of the golden byte pins. */
export function isPinnedPath(path) {
  if (typeof path !== 'string' || path === '') return false;
  const p = path.replaceAll('\\', '/').replace(/^\.\//, '');
  for (const root of PINNED_ROOTS) {
    if (root.kind === 'dir') {
      // The trailing slash is load-bearing: a sibling directory named
      // `v2-golden-archive` must not be swept into the gate.
      if (p === root.path || p.startsWith(`${root.path}/`)) return true;
    } else if (p === root.path || p.endsWith(`/${root.path}`)) {
      return true;
    }
  }
  return false;
}

/**
 * The guard the policy turns on: every watched root must actually exist. A
 * gate pointed at paths that moved protects nothing — it reports green forever
 * while the real pins sit unwatched. Relocating the fixtures must therefore
 * break this loudly, not silently ungate.
 */
export function missingPinnedRoots(repo = REPO_ROOT) {
  const missing = [];
  for (const root of PINNED_ROOTS) {
    const abs = join(repo, root.guard);
    if (!existsSync(abs)) {
      missing.push({ ...root, problem: 'not found' });
      continue;
    }
    const isDir = statSync(abs).isDirectory();
    if (root.kind === 'dir' && !isDir) {
      missing.push({ ...root, problem: 'expected a directory' });
    } else if (root.kind === 'basename' && isDir) {
      missing.push({ ...root, problem: 'expected a file' });
    }
  }
  return missing;
}

/**
 * Git's trailer rule, implemented locally so the gate does not depend on a
 * `git interpret-trailers` version: trailers live in the LAST paragraph of the
 * message, that paragraph must be all `Token: value` lines (plus folded
 * continuations and `#` comments), and a message that is only a subject line
 * has no trailers at all.
 *
 * Doing it this way — rather than grepping the message — is what lets a commit
 * *discuss* `Rebuild-Window: R1` in prose without flagging itself.
 */
export function parseTrailers(message) {
  const lines = String(message ?? '')
    .replaceAll('\r\n', '\n')
    .split('\n');

  let end = lines.length;
  while (end > 0 && lines[end - 1].trim() === '') end -= 1;
  if (end === 0) return [];
  let start = end;
  while (start > 0 && lines[start - 1].trim() !== '') start -= 1;
  // start === 0 means the whole message is one paragraph, i.e. a bare subject.
  if (start === 0) return [];

  const parsed = [];
  for (const line of lines.slice(start, end)) {
    if (line.startsWith('#')) continue;
    if (/^[ \t]/.test(line)) {
      if (parsed.length === 0) return [];
      parsed[parsed.length - 1].value += ` ${line.trim()}`;
      continue;
    }
    const m = /^([A-Za-z][A-Za-z0-9-]*)[ \t]*:[ \t]*(.*)$/.exec(line);
    // One non-trailer line disqualifies the paragraph — that is git's rule and
    // it is the reason a prose sign-off cannot masquerade as a flag.
    if (!m) return [];
    parsed.push({ key: m[1], value: m[2].trim() });
  }
  return parsed;
}

/** All `Rebuild-Window` trailer values on a commit message, in order. */
export function rebuildWindowValues(message) {
  return parseTrailers(message)
    .filter((t) => t.key.toLowerCase() === TRAILER_KEY.toLowerCase())
    .map((t) => t.value);
}

/**
 * Is this commit flagged as rebuild-window work? Only `R1` counts: a future
 * window is a decision that should edit this file, not slip through on a value
 * nobody agreed to.
 */
export function isFlagged(message) {
  return rebuildWindowValues(message).some(
    (v) => v.toUpperCase() === TRAILER_VALUE,
  );
}

function git(repo, args, { allowFail = false } = {}) {
  try {
    return execFileSync('git', ['-c', 'core.quotePath=false', ...args], {
      cwd: repo,
      encoding: 'utf8',
      maxBuffer: 64 * 1024 * 1024,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (err) {
    if (allowFail) return null;
    throw err;
  }
}

function revParse(repo, ref) {
  const out = git(
    repo,
    ['rev-parse', '--verify', '--quiet', `${ref}^{commit}`],
    {
      allowFail: true,
    },
  );
  return out ? out.trim() : null;
}

function mergeBase(repo, a, b) {
  if (!revParse(repo, a) || !revParse(repo, b)) return null;
  const out = git(repo, ['merge-base', a, b], { allowFail: true });
  return out ? out.trim() : null;
}

/**
 * Where the branch forked. Explicit wins, then the env, then GitHub's PR base
 * if it happens to be set, then a merge-base with main. Never guesses `HEAD~1`:
 * a wrong base silently narrows the gate, and narrowing a gate is the failure
 * mode this whole file exists to prevent.
 */
export function resolveBase(repo = REPO_ROOT, opts = {}) {
  const env = opts.env ?? process.env;
  const explicit = opts.base ?? env.GOLDEN_PINS_BASE;
  if (explicit) {
    const sha = revParse(repo, explicit);
    if (!sha) {
      return {
        sha: null,
        label: explicit,
        source: 'explicit',
        resolved: false,
      };
    }
    return { sha, label: explicit, source: 'explicit', resolved: true };
  }

  const candidates = [];
  if (env.GITHUB_BASE_REF) {
    candidates.push([`origin/${env.GITHUB_BASE_REF}`, 'GITHUB_BASE_REF']);
    candidates.push([env.GITHUB_BASE_REF, 'GITHUB_BASE_REF']);
  }
  candidates.push(['origin/main', 'merge-base with origin/main']);
  candidates.push(['main', 'merge-base with main']);

  for (const [ref, source] of candidates) {
    const base = mergeBase(repo, 'HEAD', ref);
    if (base) return { sha: base, label: ref, source, resolved: true };
  }
  return { sha: null, label: null, source: 'none', resolved: false };
}

/**
 * Record separator: a NUL cannot occur in a commit message, so it is the only
 * safe delimiter. It has to be spelled `%x00` in the format ARGUMENT — Node
 * refuses to spawn a child process with a NUL byte anywhere in argv — and git
 * expands it on the way out, which is what `NUL` then splits on.
 */
const NUL_FMT = '%x00';
const NUL = '\u0000';

/** Commits in `base..head`, each with its raw message and touched paths. */
export function commitsInRange(repo, base, head = 'HEAD') {
  const out = git(repo, [
    'log',
    // Merges author no pin changes of their own, and `--name-only` on a merge
    // reports only conflicted paths; the merged commits are in the range
    // anyway, so skipping merges loses nothing and avoids a false green.
    '--no-merges',
    // A gate that watches paths must see a rename as delete + add, or moving a
    // pin file out of the tree reads as "one file touched, new name only".
    '--no-renames',
    '--name-only',
    `--format=${NUL_FMT}%H${NUL_FMT}%B${NUL_FMT}`,
    `${base}..${head}`,
  ]);

  const commits = [];
  const parts = out.split(NUL);
  // Each record is `\0<sha>\0<message>\0\n<file>\n<file>\n\n`, so parts[0] is
  // the empty string before the first separator and every commit is a triple.
  for (let i = 1; i + 2 < parts.length; i += 3) {
    const sha = parts[i];
    const message = parts[i + 1];
    const files = (parts[i + 2] ?? '')
      .split('\n')
      .map((s) => s.trim())
      .filter(Boolean);
    commits.push({
      sha: sha.trim(),
      message,
      subject: message.split('\n')[0].trim(),
      files,
    });
  }
  return commits;
}

/**
 * Uncommitted pin churn, for the opt-in `--working-tree` mode. Off by default
 * on purpose: when this gate landed, the tree already carried in-flight golden
 * churn from the byte-break wave, and the gate enforces from the commit that
 * lands it forward — it is not a licence to rewrite work already in progress.
 *
 * That is still true, and got louder when the reader-side tree joined
 * `PINNED_ROOTS` on 2026-08-10: `--working-tree` now also reports the ~120
 * uncommitted objects under `packages/core/test/fixtures/` from the same
 * in-flight v2→v3 break. Reporting them is CORRECT. Do not silence it by
 * narrowing the watched set — a gate narrowed to stay quiet is the exact
 * failure this file exists to prevent — and do not "clean" the churn either;
 * it belongs to the rebuild window, and the commit that lands it carries the
 * trailer.
 */
export function workingTreeChanges(repo) {
  const out = git(repo, [
    'status',
    '--porcelain=v1',
    '--untracked-files=all',
    '-z',
  ]);
  const tokens = out.split(NUL);
  const files = [];
  for (let i = 0; i < tokens.length; i += 1) {
    const entry = tokens[i];
    if (!entry) continue;
    const status = entry.slice(0, 2);
    files.push(entry.slice(3));
    // With -z a rename/copy emits the origin path as the very next token.
    if (status.includes('R') || status.includes('C')) {
      i += 1;
      if (tokens[i]) files.push(tokens[i]);
    }
  }
  return files.filter((f) => isPinnedPath(f));
}

/** The whole check, as data. `main()` only renders it. */
export function checkGoldenPins(opts = {}) {
  const repo = opts.repo ?? REPO_ROOT;
  const head = opts.head ?? 'HEAD';

  const missingRoots = missingPinnedRoots(repo);
  if (missingRoots.length > 0) {
    return { ok: false, reason: 'guard', repo, missingRoots };
  }

  const base = opts.baseInfo ?? resolveBase(repo, opts);
  if (!base.resolved) {
    return { ok: false, reason: 'no-base', repo, base };
  }

  const commits = commitsInRange(repo, base.sha, head);
  const offenders = [];
  const flagged = [];
  for (const c of commits) {
    const pinned = c.files.filter((f) => isPinnedPath(f));
    if (pinned.length === 0) continue;
    const entry = {
      sha: c.sha,
      subject: c.subject,
      files: pinned,
      trailers: rebuildWindowValues(c.message),
    };
    if (isFlagged(c.message)) flagged.push(entry);
    else offenders.push(entry);
  }

  if (opts.workingTree) {
    const dirty = workingTreeChanges(repo);
    if (dirty.length > 0) {
      offenders.push({
        sha: null,
        subject: '(uncommitted working-tree changes)',
        files: dirty,
        trailers: [],
      });
    }
  }

  return {
    ok: offenders.length === 0,
    reason: offenders.length === 0 ? null : 'unflagged',
    repo,
    base,
    head,
    range: `${base.label ?? base.sha.slice(0, 12)}..${head}`,
    commitsChecked: commits.length,
    offenders,
    flagged,
  };
}

/**
 * "Which tree did I just touch, and what regenerates it?" — rendered from
 * `PINNED_ROOTS` so adding a watched tree cannot leave the teaching message
 * pointing at the old one.
 */
const TREE_GUIDE = PINNED_ROOTS.filter((r) => r.kind === 'dir')
  .map(
    (r) =>
      `      ${r.path}\n` +
      `          oracle:     ${r.oracle}\n` +
      `          regenerate: ${r.regen}`,
  )
  .join('\n');

const RATIONALE = `
Why this is a gate and not a nit:

  The golden fixtures are the format's regression oracles — the writer's
  (${ORACLE_TEST}) and the reader's, which pin the same
  bytes from the other side. Determinism is the format's economic contract, not
  a nicety — packs are content-addressed, so identical input MUST encode to
  identical bytes on every machine or the fleet stops deduplicating across
  deploys. The two pin movements in this project's history each forced a full
  re-upload; the 2026-07-26 break cost 29.3 GiB across 1,324 objects, 100%
  re-uploaded (docs/roadmap/optimization-problems-2026-08.md §13.1).

  Both sides are watched on purpose. A reader-side fixture re-blessed on its own
  is the worse case, not the milder one: it hides an encoder change behind a
  reader that has been taught to accept it, and the writer's oracle stays green
  while the bytes on the fleet have already moved.

  So a pin change is a DECISION, not a fixup. Exactly one is planned in this
  program: the Phase 4 rebuild window R1 — "Golden byte pins change once,
  intentionally, reviewed" (docs/roadmap/optimization-informed-design-2026-08.md §6).

If a golden test went red and you did NOT mean to move bytes:
  You have an encoder bug. Fix the encoder. Re-blessing the fixture deletes the
  only evidence that anything changed.
  Regenerate ONLY as part of a reviewed rebuild, and only with the regenerator
  belonging to the tree you touched:

${TREE_GUIDE}

If you ARE doing rebuild-window work, the flag is deliberately cheap — one
trailer on the commit that moves the bytes:

      git commit --trailer '${TRAILER_KEY}: ${TRAILER_VALUE}' ...
      git commit --amend --trailer '${TRAILER_KEY}: ${TRAILER_VALUE}'   # already committed

  The trailer must be in the commit message's LAST paragraph. Naming it in
  prose does not count, on purpose.
`;

function renderFailure(report) {
  if (report.reason === 'guard') {
    console.error('golden pins: the gate no longer matches the tree.\n');
    for (const r of report.missingRoots) {
      console.error(`  ${r.guard} — ${r.problem}`);
      console.error(`      watches: ${r.what}`);
    }
    console.error(
      '\nA gate pointed at paths that moved protects nothing: it would report green\n' +
        'forever while the real pins sat unwatched. If the fixtures moved on purpose,\n' +
        'update PINNED_ROOTS in .github/scripts/check-golden-pins.mjs to follow them.\n' +
        'Do not delete this check to make it quiet.',
    );
    return;
  }

  if (report.reason === 'no-base') {
    console.error(
      'golden pins: could not resolve a base commit to diff against.\n',
    );
    console.error(
      `  tried: ${report.base.label ?? 'origin/main, main'} (${report.base.source})\n`,
    );
    console.error(
      'Pass one explicitly, or give CI full history:\n' +
        '      node .github/scripts/check-golden-pins.mjs --base <ref>\n' +
        '      actions/checkout@v4 with: { fetch-depth: 0 }\n\n' +
        'Failing closed is deliberate — an unresolved base would silently check\n' +
        'nothing at all.',
    );
    return;
  }

  const n = report.offenders.length;
  console.error(
    `golden pins: ${n} change(s) moved a golden byte pin without a ` +
      `\`${TRAILER_KEY}: ${TRAILER_VALUE}\` trailer.\n`,
  );
  for (const o of report.offenders) {
    const id = o.sha ? o.sha.slice(0, 12) : 'working tree';
    console.error(`  ${id}  ${o.subject}`);
    for (const f of o.files) console.error(`      ${f}`);
    if (o.trailers.length > 0) {
      console.error(
        `      found \`${TRAILER_KEY}: ${o.trailers.join(', ')}\` — ` +
          `expected \`${TRAILER_VALUE}\``,
      );
    }
    console.error('');
  }
  console.error(RATIONALE.trim());
}

export function main(argv = process.argv.slice(2)) {
  if (argv.includes('--help') || argv.includes('-h')) {
    console.log(
      'Usage: node .github/scripts/check-golden-pins.mjs [options]\n\n' +
        '  --base <ref>     commit to diff from (default: merge-base with origin/main)\n' +
        '  --head <ref>     commit to diff to (default: HEAD)\n' +
        '  --repo <dir>     repository to check (default: this repo)\n' +
        '  --working-tree   also flag uncommitted pin changes (default: off)\n',
    );
    return 0;
  }

  const flag = (name) => {
    const i = argv.indexOf(name);
    return i >= 0 && i + 1 < argv.length ? argv[i + 1] : undefined;
  };

  let report;
  try {
    report = checkGoldenPins({
      repo: flag('--repo') ? resolve(flag('--repo')) : REPO_ROOT,
      base: flag('--base'),
      head: flag('--head'),
      workingTree: argv.includes('--working-tree'),
    });
  } catch (err) {
    // Fail closed. A gate that exits 0 because git misbehaved is worse than no
    // gate: it reports "checked" while having checked nothing.
    console.error('golden pins: the check could not run.\n');
    console.error(`  ${err.stderr?.toString().trim() || err.message}\n`);
    console.error(
      'This is a hard failure on purpose — an unrunnable gate must not read as\n' +
        'a passing one. Fix the invocation (see --help) and re-run.',
    );
    return 1;
  }

  if (!report.ok) {
    renderFailure(report);
    return 1;
  }

  const flaggedNote =
    report.flagged.length > 0
      ? `, ${report.flagged.length} pin change(s) flagged \`${TRAILER_KEY}: ${TRAILER_VALUE}\``
      : ', none touch the pins';
  console.log(
    `golden pins: ${report.commitsChecked} commit(s) checked in ${report.range}${flaggedNote}.`,
  );
  return 0;
}

const invokedDirectly =
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) process.exit(main());
